// b22o1 is the order-1 part of block pphhhh,pphhhh, <a,b,i,j,k,l|M|c,d,m,n,o,i1>.
func (el *Elem) b22o1(a, b, i, j, k, l, c, d, m, n, o, i1 int) float64 {
	var v float64
	// (1)
	v += el.b22o1g0(a, b, i, j, k, l, c, d, m, n, o, i1)
	return v
}

// B22 is block pphhhh,pphhhh of the secular matrix,
// <a,b,i,j,k,l|M|c,d,m,n,o,i1>, summed over the orders the scheme keeps.
func (el *Elem) B22(a, b, i, j, k, l, c, d, m, n, o, i1 int) float64 {
	var v float64
	if el.maxOrder[5] >= 0 {
		v += el.b22o0(a, b, i, j, k, l, c, d, m, n, o, i1)
	}
	if el.maxOrder[5] >= 1 {
		v += el.b22o1(a, b, i, j, k, l, c, d, m, n, o, i1)
	}
	return v
}
